const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

// Plain text of a Lark message of any type, for reading and for thread history.
const plainOf = (msg) => {
  const raw = (msg && msg.body && msg.body.content) || '';
  try {
    const c = JSON.parse(raw || '{}');
    if (msg.msg_type === 'text') return c.text || '';
    if (msg.msg_type === 'post') {
      const blocks = Array.isArray(c.content) ? c.content : [];
      return [c.title || '', ...blocks.map((line) => (Array.isArray(line) ? line : []).map((el) => (el.tag === 'img' ? '[picture]' : el.text || el.href || '')).join(''))].filter(Boolean).join('\n');
    }
    if (msg.msg_type === 'image') return '[picture]';
    return JSON.stringify(c).replace(/"(tag|type|template|schema|behaviors|value|width|flex_mode|img_key|image_key)":"[^"]*",?/g, '').replace(/[{}\[\]"]/g, ' ').replace(/\s+/g, ' ').trim();
  } catch (e) {
    return String(raw).slice(0, 2000);
  }
};

const input = $('When called').first().json;
const settings = settingsOf('Load settings');
const r = $json;
if (r.code !== 0) throw new Error(`Lark get message failed: ${r.code} ${r.msg}`);
const m = ((r.data && r.data.items) || [])[0];
if (!m || !m.sender || m.sender.sender_type !== 'user') return [];

const mentions = Array.isArray(m.mentions) ? m.mentions : [];
const botMentioned = mentions.some((x) => x.id === settings.lark_bot_open_id);
let text = plainOf(m);
for (const x of mentions) text = text.split(x.key).join(x.id === settings.lark_bot_open_id ? '' : `@${x.name}`);
text = text.replace(/\[picture\]/g, '').trim();
const images = [];
try {
  const c = JSON.parse((m.body && m.body.content) || '{}');
  if (m.msg_type === 'image' && c.image_key) images.push(c.image_key);
  if (m.msg_type === 'post') (Array.isArray(c.content) ? c.content : []).flat().forEach((el) => { if (el && el.tag === 'img' && el.image_key) images.push(el.image_key); });
} catch (e) {}
if (!text && !images.length) return [];

const isCommand = text.startsWith('/');
const word = isCommand ? text.split(/\s+/)[0] : '';
const command = word.slice(1).toLowerCase();
const args = isCommand ? text.slice(word.length).trim() : '';
const group = input.chat_type === 'group';
const sender = m.sender.id;
const rowId = (key) => { const j = $('Load settings').all().map((i) => i.json).find((x) => x.fields && x.fields.key === key); return j ? j.id : null; };
const base = { text, images, command, args, is_command: isCommand, group, chat_id: m.chat_id, sender, message_id: m.message_id, parent_id: m.parent_id || '', root_id: m.root_id || '', thread_id: m.thread_id || '', auth: $('Get Lark token').first().json.tenant_access_token };

if (!group) {
  if (!settings.lark_open_id) return [{ json: { ...base, access: 'link_owner', settings_row_id: rowId('lark_open_id') } }];
  if (sender !== settings.lark_open_id) return [];
  return [{ json: { ...base, access: 'ok' } }];
}
const team = settings.lark_chat_id && m.chat_id === settings.lark_chat_id;
if (!isCommand && !botMentioned) {
  // Replies in a thread the bot started count as talking to it; Decide checks who started it.
  return team && (m.root_id || m.thread_id) ? [{ json: { ...base, access: 'thread_check' } }] : [];
}
if (command === 'link') {
  if (sender !== settings.lark_open_id) return [{ json: { ...base, access: 'reply', reply: 'Only the owner (the person who first messaged me directly) can link a group.' } }];
  return [{ json: { ...base, access: 'link_group', settings_row_id: rowId('lark_chat_id') } }];
}
if (!team) {
  return [{ json: { ...base, access: 'reply', reply: 'This group is not my team chat. The owner can send /link here to make it one.' } }];
}
return [{ json: { ...base, access: 'ok' } }];

