// action: 0 link, 1 reply only, 2 instant command, 3 attach pictures to a post, 4 capture inspiration, 5 nothing more
const m = $('Read message').first().json;
const settings = settingsOf('Load settings');
const members = (($('Fetch members').first().json.data || {}).items || []);
const names = Object.fromEntries(members.map((x) => [x.member_id, x.name]));
const nameOf = (id) => (id === settings.lark_bot_open_id ? 'You (the agent)' : names[id] || (id === settings.lark_open_id ? 'The owner' : 'A team member'));
const found = (($('Fetch thread').first().json.data || {}).items || []).filter((x) => x.message_id !== m.message_id);
const history = found.slice(-30).map((x) => `${nameOf(x.sender && x.sender.id)}: ${plainOf(x).slice(0, 1500)}`);
const rootText = found.map((x) => (x.body && x.body.content) || '').join('\n');
const post = rootText.match(/[Pp]ost #(\d+)/);
const offer = rootText.match(/[Oo]ffer #(\d+)/);
const postId = post ? Number(post[1]) : null;
const offerId = offer ? Number(offer[1]) : null;
const who = nameOf(m.sender);
const out = { ...m, history, post_id: postId, offer_id: offerId, who, reply_to: m.message_id, thread_key: m.root_id || m.message_id };

const INSTANT = ['help', 'status', 'story', 'inspiring'];
const AGENT = ['rule', 'goal', 'offers', 'plan', 'draft', 'review'];
let action = 5;
let agent = false;
let reply = '';
const root = found.find((x) => x.message_id === m.root_id) || found[0];
if (m.access === 'thread_check' && !(root && root.sender && root.sender.id === settings.lark_bot_open_id)) {
  return [{ json: { ...out, action: 5, agent: false, reply: '' } }];
}
if (m.access === 'reply') { action = 1; reply = m.reply; }
else if (m.access === 'link_owner') { action = 0; agent = true; }
else if (m.access === 'link_group') { action = 0; }
else if (m.is_command && INSTANT.includes(m.command)) { action = 2; }
else if (m.is_command && AGENT.includes(m.command)) { agent = true; }
else if (m.is_command) { action = 1; reply = `I don't know /${m.command}.\n\n${"Commands (in the group, write them as they are or after @mentioning me):\n/story <what happened>: save a real moment for future stories\n/inspiring + screenshots of a post: save it as inspiration\n/status: the next 14 days\n/rule <rule>: a rule I always follow from now on\n/goal <goal>: set or change a goal\n/offers [YYYY-MM]: propose offers (default next month)\n/plan [notes]: plan every free day up to the last approved offer\n/draft <post id> [notes]: write that post now\n/review: run the weekly review now\n/link: (in a group, by the owner) make this group the team chat\nAnything else: @mention me and talk. In threads I started (cards, questions, my answers) no @mention is needed. Reply to a draft card in its thread to change it, or with photos to add pictures to that post."}`; }
else if (m.images.length && postId) { action = 3; agent = Boolean(m.text); }
else if (m.images.length && !m.group) { action = 4; }
else if (m.images.length) { action = 1; reply = 'To save a post as inspiration, send its screenshots with /inspiring. To add pictures to a planned post, reply to its draft card with them.'; }
else { agent = true; }
return [{ json: { ...out, action, agent, reply } }];

const d = $('Decide').first().json;
const text = String($json.result || 'Could not read the calendar.');
return [{ json: { reply_to: d.reply_to, text: text.length > 8000 ? `${text.slice(0, 8000)}\n…` : text } }];

