const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

const d = $('Decide').first().json;
const p = rowsOf('Picture post')[0];
if (!p) return [{ json: { ok: false, reply_to: d.reply_to, text: `Post #${d.post_id} does not exist.` } }];
if (!['planned', 'awaiting_approval', 'approved', 'publish_failed'].includes(p.status)) {
  return [{ json: { ok: false, reply_to: d.reply_to, text: `Post #${p.Id} is ${p.status}; the picture was not added.` } }];
}
const lines = (p.images || '').split('\n').filter((l) => l.trim());
d.images.forEach((key) => lines.push(`${d.message_id} ${key}`));
const kept = lines.slice(-10);
return [{
  json: {
    ok: true,
    Id: p.Id,
    images: kept.join('\n'),
    reply_to: d.reply_to,
    text: `📷 Got ${d.images.length} picture${d.images.length > 1 ? 's' : ''} for post #${p.Id}. ${kept.length > 1 ? `All ${kept.length} go` : 'It goes'} out with it.${lines.length > 10 ? ' Facebook takes 10 at most, so only the last 10 are kept.' : ''}`,
    event: `${d.who} sent ${d.images.length} picture(s) for post #${p.Id} "${p.title}"`,
  },
}];

const d = $('Decide').first().json;
const lines = [];
if (d.access === 'link_owner') lines.push('(This is the first message from the owner: introduce yourself in two lines and, if goals or brand docs are missing, ask for them.)');
if (d.history.length) lines.push(`Conversation so far in this thread:\n${d.history.join('\n')}`);
if (d.post_id || d.offer_id) lines.push(`This thread is about ${d.post_id ? `post #${d.post_id}` : `offer #${d.offer_id}`}.`);
lines.push(`${d.who} wrote now: <<<\n${d.text}\n>>>`);
const mode = d.is_command ? (d.command === 'review' ? 'review' : 'command') : 'chat';
return [{
  json: {
    mode,
    command: d.is_command ? d.command : '',
    args: d.args,
    text: lines.join('\n\n'),
    reply_to: d.reply_to,
    event: {
      type: (d.post_id && (d.parent_id || d.thread_id)) ? 'change_request' : 'manager_note',
      post_id: d.post_id,
      offer_id: d.offer_id,
      text: `${d.who}: ${d.text}`,
    },
  },
}];
